// Loads the acquisition's extensions through target.extensions.load, one after another. Returns what
// that load returns: for a single extension the very value of the call, for several a promise that
// resolves after the last. target is the UI's lua bridge, or any object with the same
// extensions.load/unload.
export function acquireScope(target, id, { mode } = {}) {
  const acquisition = entry(id)
  if (mode && acquisition.modes && !acquisition.modes[mode]) throw new Error(`Lua scope acquisition ${id} is unavailable in ${mode}`)
  const names = acquisition.extensions
  let result = target.extensions.load(names[0])
  holdScopeAcquisition(target, id, acquisition)
  for (let i = 1; i < names.length; i++) {
    const name = names[i]
    result = Promise.resolve(result).then(() => target.extensions.load(name))
  }
  if (acquisition.stateOwner) {
    result = Promise.resolve(result).then(async loaded => {
      if (isScopeAcquisitionHeld(target, id, acquisition)) await target[acquisition.stateOwner].onUiScopeChanged(id, true)
      return loaded
    })
  }
  return result
}

// Unloads what the acquisition names for release, in the order listed; returns the last call's value.
export function releaseScope(target, id) {
  const acquisition = releaseScopeAcquisition(target, id) || entry(id)
  const unload = () => {
    let result
    for (const name of acquisition.release) result = target.extensions.unload(name)
    return result
  }
  if (acquisition.stateOwner) return Promise.resolve(target[acquisition.stateOwner].onUiScopeChanged(id, false)).then(unload)
  return unload()
}
